<script setup lang="ts">
import {ref,reactive,onMounted} from 'vue'
import {api,message,notify,date} from '../api'
const data=ref<any>({members:[],works:[]}),tab=ref('社员名册'),error=ref(''),tag=reactive({name:'',description:'',isActivity:true}),busy=ref(false)
async function load(){error.value='';try{data.value=(await api.get('/admin/overview')).data}catch(e){error.value=message(e)}}
async function withdraw(id:number){if(!confirm('确认下架这篇作品？'))return;try{await api.post(`/admin/works/${id}/withdraw`);await load();notify('作品已下架')}catch(e){notify(message(e))}}
async function createTag(){busy.value=true;try{await api.post('/admin/tags',tag);tag.name='';tag.description='';notify('标签已创建')}catch(e){notify(message(e))}finally{busy.value=false}}
onMounted(load)
</script>
<template><div class="container page-space"><div class="section-heading"><div><p class="eyebrow">管理</p><h1 class="page-title">社务台</h1></div><RouterLink to="/admin/settings" class="button secondary">后台配置</RouterLink></div><div class="desk-stats"><div><strong>{{data.members.length}}</strong><span>社员</span></div><div><strong>{{data.works.filter((w:any)=>w.status==='PUBLISHED').length}}</strong><span>近期公开作品</span></div></div><div class="genre-tabs desk-tabs"><button v-for="t in ['社员名册','稿件管理','活动标签']" :key="t" :class="{selected:tab===t}" @click="tab=t">{{t}}</button></div><p v-if="error" class="error-message">{{error}}</p><div v-if="tab==='社员名册'" class="table-wrap"><table><thead><tr><th>笔名</th><th>账号</th><th>身份</th><th>加入时间</th><th></th></tr></thead><tbody><tr v-for="m in data.members" :key="m.id"><td>{{m.penName}}</td><td>{{m.username}}</td><td>{{m.role==='ADMIN'?'管理员':'社员'}}</td><td>{{date(m.createdAt)}}</td><td><RouterLink to="/admin/settings">配置权限</RouterLink></td></tr></tbody></table></div><div v-else-if="tab==='稿件管理'" class="table-wrap"><p class="quiet-note">展示最近 100 篇稿件</p><table><thead><tr><th>作品</th><th>作者</th><th>状态</th><th></th></tr></thead><tbody><tr v-for="w in data.works" :key="w.id"><td><RouterLink v-if="w.status==='PUBLISHED'" :to="`/work/${w.id}`">{{w.title}}</RouterLink><span v-else>{{w.title||'未命名稿件'}}</span></td><td>{{w.authorName}}</td><td>{{w.status==='PUBLISHED'?'公开':w.status==='DRAFT'?'草稿':'已撤回'}}</td><td><button v-if="w.status==='PUBLISHED'" @click="withdraw(w.id)">下架</button></td></tr></tbody></table></div><form v-else class="panel profile-form" @submit.prevent="createTag"><h2>新增标签或征稿主题</h2><label>名称<input v-model="tag.name" maxlength="30" required/></label><label>说明<textarea v-model="tag.description" maxlength="300" rows="3"></textarea></label><label class="checkbox-label"><input type="checkbox" v-model="tag.isActivity"/>同时展示在“征稿与活动”</label><button class="button" :disabled="busy">创建标签</button></form></div></template>
